// Velocidad 0..100 (% de PWM). Con batería de 9 V y motor de 6 V, no pasar de ~70.
const SPEED = Number(msg.speed ?? 30);
let dir;
switch (msg.payload) {
    case "adelante": dir = 0; break;
    case "atras":    dir = 1; break;
    default:         // stop
        node.status({fill:"red",shape:"dot",text:"stop"});
        return [{payload:0},{payload:0},{payload:0},{payload:0},{payload:0},{payload:0}];
}
node.status({fill:"green",shape:"dot",text:msg.payload+" "+SPEED+"%"});
// [Izq PWM, Izq 1, Izq 2, Der PWM, Der 1, Der 2]
return [{payload:SPEED},{payload:dir},{payload:dir?0:1},
        {payload:SPEED},{payload:dir},{payload:dir?0:1}];

const p = msg.payload;
if (!p || typeof p !== "object" || typeof p.detectado !== "boolean" || typeof p.modo !== "string") {
    node.warn("Mensaje de visión inválido; se esperaba un objeto JSON con detectado y modo");
    return null;
}
const x = Number.isFinite(p.x) ? Math.max(0, Math.min(1, p.x)) : null;
const area = Number.isFinite(p.area) ? Math.max(0, p.area) : null;
const permitidos = new Set(["verde", "rojo", "amarillo"]);
const listaColores = p.detectado && Array.isArray(p.colores)
    ? [...new Set(p.colores.filter(color => permitidos.has(color)))] : [];
const color = permitidos.has(p.color) ? p.color : (listaColores[0] || null);
const colores = listaColores.length ? listaColores : (p.detectado && color ? [color] : []);
const anterior = global.get("robot_vision");
const recibido = Date.now();
const coloresUltimo = colores.length ? colores : (anterior && Array.isArray(anterior.colores_ultimo) ? anterior.colores_ultimo : []);
const colorRecibido = colores.length ? recibido : (anterior && Number.isFinite(anterior.color_recibido) ? anterior.color_recibido : null);
const mensajesRecientes = anterior && Number.isFinite(anterior.recibido) && recibido - anterior.recibido < 300
    ? Math.min(3, (Number(anterior.mensajes_recientes) || 1) + 1) : 1;
const ultimoDetectado = p.detectado && x !== null ? recibido : (anterior && Number.isFinite(anterior.ultimo_detectado) ? anterior.ultimo_detectado : null);
const ultimaX = p.detectado && x !== null ? x : (anterior && Number.isFinite(anterior.ultima_x) ? anterior.ultima_x : null);
global.set("robot_vision", {
    activo: true,
    detectado: p.detectado,
    modo: p.modo,
    color,
    colores,
    colores_ultimo: coloresUltimo,
    color_recibido: colorRecibido,
    x,
    area,
    texto: typeof p.texto === "string" ? p.texto : null,
    recibido,
    ultimo_detectado: ultimoDetectado,
    ultima_x: ultimaX,
    mensajes_recientes: mensajesRecientes
});
node.status({ fill: p.detectado ? "green" : "grey", shape: "dot", text: p.modo + (p.detectado ? " detectado" : " sin objeto") });
return msg;

// ===== Configuración =====
const MAX_SPEED   = 80;   // tope de velocidad (%), batería 9 V / motor 6 V
const SERVO_LEFT   = 500;   // µs izquierda total (calibrado)
const SERVO_CENTER = 1200;  // µs recto (calibrado)
const SERVO_RIGHT  = 2500;  // µs derecha total (calibrado)
const BRAKE_MS    = 200;  // pausa al cambiar de sentido
const GIRO_IZQ    = 40;   // % máximo de giro a la IZQUIERDA (100 = tope del servo)
const GIRO_DER    = 40;   // % máximo de giro a la DERECHA
const EXTRA_GIRO  = 15;   // % de velocidad extra al doblar (las ruedas giradas frenan el robot)
const LIMITE_CM   = 25;   // distancia de freno si todavía no hay lectura (la real la calcula "Distancia y freno")

// Estado actual (se guarda entre mensajes)
let st = flow.get("robot") || { cmd: "stop", speed: 60, steer: 0, auto: false };
if (typeof st.auto !== "boolean") st.auto = false;
const prevCmd = st.cmd;

// Leer lo que mandó el tablero (o el inject de inicio)
const p = (typeof msg.payload === "object" && msg.payload) ? msg.payload : {};
if (typeof p.auto === "boolean") {
    const estabaEnAuto = st.auto;
    st.auto = p.auto;
    if (p.auto || estabaEnAuto) { st.cmd = "stop"; st.steer = 0; }
}
if (["adelante", "atras", "stop"].includes(p.cmd)) {
    if (p.origen !== "vision") st.auto = false;
    st.cmd = p.cmd;
}
if (p.speed !== undefined && !isNaN(p.speed)) st.speed = Math.max(0, Math.min(MAX_SPEED, Number(p.speed)));
if (p.steer !== undefined && !isNaN(p.steer)) st.steer = Math.max(-100, Math.min(100, Number(p.steer)));
// Freno por obstáculo: no permite avanzar si hay algo muy cerca (atrás sí)
const dist = flow.get("distancia");
const frenoCm = flow.get("frenoCm") || LIMITE_CM;
const sensorCaido = Date.now() - (flow.get("tLectura") || 0) > 1500;   // sin datos: no deja avanzar
st.sensorCaido = sensorCaido;
st.bloqueado = st.cmd === "adelante" && (sensorCaido || (typeof dist === "number" && dist < frenoCm));
if (st.bloqueado) {
    st.cmd = "stop";
    st.steer = 0;
    st.auto = false;
}
flow.set("robot", st);

// ---- Motor: [Izq PWM, Izq 1, Izq 2, Der PWM, Der 1, Der 2] ----
function pines(pwm, dir) {
    return [{payload:pwm},{payload:dir},{payload:dir?0:1},
            {payload:pwm},{payload:dir},{payload:dir?0:1}];
}
const STOP = [{payload:0},{payload:0},{payload:0},{payload:0},{payload:0},{payload:0}];

// ---- Servo: steer -100..100 -> valor 0..100 del nodo servo ----
// Se limita el giro para que las ruedas no choquen con la estructura
let s = st.steer < 0 ? st.steer * GIRO_IZQ / 100 : st.steer * GIRO_DER / 100;
let servo = s < 0 ? SERVO_CENTER + (s / 100) * (SERVO_CENTER - SERVO_LEFT)
                  : SERVO_CENTER + (s / 100) * (SERVO_RIGHT - SERVO_CENTER);
servo = Math.round((servo - 500) / 20);   // µs → 0..100 para el nodo (500..2500)

// Cancelar un arranque pendiente
clearTimeout(context.get("t"));
context.set("t", null);

let motorMsgs;
if (st.cmd === "stop") {
    motorMsgs = STOP;
} else {
    const dir = st.cmd === "atras" ? 1 : 0;
    const vel = Math.min(MAX_SPEED, st.speed + EXTRA_GIRO * Math.abs(st.steer) / 100);
    const cambioSentido = (prevCmd === "adelante" && st.cmd === "atras") ||
                          (prevCmd === "atras" && st.cmd === "adelante");
    if (cambioSentido) {
        // frenar, esperar y recién ahí arrancar en el otro sentido
        motorMsgs = pines(0, dir);
        context.set("t", setTimeout(() => {
            node.send([...pines(vel, dir), null, null]);
        }, BRAKE_MS));
    } else {
        motorMsgs = pines(vel, dir);
    }
}

node.status({
    fill: st.cmd === "stop" ? "red" : "green", shape: "dot",
    text: st.cmd + " " + st.speed + "% | giro " + st.steer + " (servo " + servo + ")"
});

// Respuesta al navegador (solo si vino del tablero)
let resp = null;
if (msg.res) {
    msg.payload = { ...st, distancia: flow.get("distancia") ?? null, cerca: !!flow.get("cerca"), luz: flow.get("luz") || "apagado", leds: global.get("robot_leds") || null, frenoCm: flow.get("frenoCm") || null };
    resp = msg;
}
return [...motorMsgs, { payload: servo }, resp];

// ===== Distancia, freno y aviso =====
// Recibe lo que imprime el sensor: distancia en cm, o -1 si no hay nada en rango
const FRENO_BASE  = 15;    // cm de freno a velocidad 0
const FRENO_K     = 0.25;  // cm extra por cada % de velocidad (a 80 % frena a 35 cm)
const AVISO_EXTRA = 20;    // el aviso empieza estos cm antes del freno

const partes = String(msg.payload).trim().split(/\s+/);
const d = Number(partes[partes.length - 1]);
const st = flow.get("robot") || { cmd: "stop", speed: 60 };

// Distancia de freno según la velocidad que lleva
const frenoCm = Math.round(FRENO_BASE + (Number(st.speed) || 0) * FRENO_K);
flow.set("frenoCm", frenoCm);
flow.set("avisoCm", frenoCm + AVISO_EXTRA);
flow.set("tLectura", Date.now());

if (isNaN(d) || d < 0) {
    // Sin eco = no hay nada delante en rango: camino libre
    flow.set("distancia", null);
    flow.set("cerca", false);
    node.status({ fill: "green", shape: "ring", text: "libre (freno a " + frenoCm + " cm)" });
    return null;
}

flow.set("distancia", d);
const cerca = d < frenoCm;
flow.set("cerca", cerca);
node.status({ fill: cerca ? "red" : (d < frenoCm + AVISO_EXTRA ? "yellow" : "green"), shape: "dot",
              text: d.toFixed(0) + " cm | freno a " + frenoCm + " cm" });

// Si va para adelante y está dentro de la distancia de freno: STOP inmediato
if (cerca && st.cmd === "adelante") return { payload: { cmd: "stop" } };
return null;

const st = flow.get("robot") || { cmd: "stop", speed: 60, steer: 0, auto: false };
if (typeof st.auto !== "boolean") st.auto = false;
st.sensorCaido = Date.now() - (flow.get("tLectura") || 0) > 1500;
// Estado de la cámara (lo guarda la pestaña "Vision RaspiRobot")
const vision = global.get("robot_vision");
const edad = vision ? Date.now() - vision.recibido : null;
const visionActiva = edad !== null && edad < 3000;
const seguimientoDisponible = visionActiva && edad < 750 && vision.detectado === true && vision.mensajes_recientes >= 3 && Number.isFinite(vision.x);
const leds = global.get("robot_leds");
msg.payload = { ...st, distancia: flow.get("distancia") ?? null, cerca: !!flow.get("cerca"),
                luz: flow.get("luz") || "apagado", leds: leds || null, frenoCm: flow.get("frenoCm") || null,
                vision: visionActiva
                    ? { ...vision, edad_ms: edad, seguimiento_disponible: seguimientoDisponible }
                    : { activo: false, detectado: null, modo: null, x: null, area: null, texto: null, edad_ms: edad } };
return msg;

// ===== Semáforo del robot =====
// Rojo GPIO 11, Amarillo GPIO 22, Verde GPIO 9 (siempre al máximo: 1 = 3,3 V)
// Distancias calculadas en "Distancia y freno" según la velocidad
const FRENO_CM = flow.get("frenoCm") || 25;   // más cerca: frena y ROJO FIJO
const AVISO_CM = flow.get("avisoCm") || 45;   // entre freno y aviso yendo adelante: ROJO PARPADEANDO
const PARPADEO_MS = 250;
// Buzzer en GPIO 15 (amarillo +, naranja − a GND)
// "activo": suena solo con corriente  |  "pasivo": necesita PWM (tono)
const BUZZER = "pasivo";   // el de ustedes es pasivo (sonó con pigs p 15 128)

const st = flow.get("robot") || { cmd: "stop" };
const d = flow.get("distancia");
const hayLectura = typeof d === "number";
const sensorCaido = Date.now() - (flow.get("tLectura") || 0) > 1500;
const obstaculo = st.bloqueado || (hayLectura && d < FRENO_CM);

let luz;
if (sensorCaido || obstaculo) {
    luz = "rojo";                                       // prioridad a sensor u obstáculo
} else if (st.cmd === "atras") {
    luz = "amarillo";                                   // marcha atrás
} else if (st.cmd === "adelante" && hayLectura && d < AVISO_CM) {
    luz = "rojo-parpadeo";                              // se está acercando a algo
} else if (st.cmd === "adelante") {
    luz = "verde";                                      // camino libre
} else {
    luz = "apagado";                                    // detenido sin obstáculo
}
flow.set("luz", luz);

const vision = global.get("robot_vision");
const ahora = Date.now();
const visionActual = vision && Number.isFinite(vision.recibido) && ahora - vision.recibido < 750;
const colorReciente = vision && Number.isFinite(vision.color_recibido) && ahora - vision.color_recibido < 750;
const coloresActuales = visionActual && vision.detectado === true && vision.modo === "color" && Array.isArray(vision.colores)
    ? vision.colores : [];
const colores = coloresActuales.length ? coloresActuales
    : visionActual && vision.modo === "color" && colorReciente && Array.isArray(vision.colores_ultimo)
        ? vision.colores_ultimo : [];
const parpadeo = luz === "rojo-parpadeo" && Math.floor(Date.now() / PARPADEO_MS) % 2 === 0;
const alarmaSeguridad = luz === "rojo" || luz === "rojo-parpadeo";
let R = (luz === "rojo" || parpadeo) ? 1 : 0;
let Y = luz === "amarillo" ? 1 : 0;
let G = luz === "verde" ? 1 : 0;
if (!alarmaSeguridad && colores.length) {
    R = colores.includes("rojo") ? 1 : 0;
    Y = colores.includes("amarillo") ? 1 : 0;
    G = colores.includes("verde") ? 1 : 0;
}

const B = alarmaSeguridad && R ? (BUZZER === "pasivo" ? 50 : 100) : 0;   // color rojo detectado no activa la alarma
const motivoSeguridad = sensorCaido ? "HC-SR04 sin datos"
    : luz === "rojo-parpadeo" ? "Obstáculo cerca"
    : obstaculo ? "Obstáculo dentro del límite" : null;
global.set("robot_leds", {
    disponible: true,
    rojo: R === 1,
    amarillo: Y === 1,
    verde: G === 1,
    buzzer: B > 0,
    seguridad: alarmaSeguridad,
    motivo: motivoSeguridad,
    colores: !alarmaSeguridad && colores.length ? colores : [],
    actualizado: Date.now()
});

// Mandar a los pines solo si cambió algo
const clave = R + "" + Y + G + B;
if (context.get("ultimo") === clave) return null;
context.set("ultimo", clave);

const color = { rojo: "red", "rojo-parpadeo": "red", amarillo: "yellow", verde: "green", apagado: "grey" }[luz];
node.status({ fill: color, shape: luz === "rojo-parpadeo" ? "ring" : "dot",
              text: luz + (hayLectura ? " | " + d.toFixed(0) + " cm" : "") });

// El buzzer suena igual que el LED rojo: fijo o intermitente

return [{ payload: R }, { payload: Y }, { payload: G }, { payload: B }];

const AUTO_SPEED = 45;
const AUTO_MAX_STEER = 60;
const DEAD_BAND = 0.08;
const STREAM_TIMEOUT_MS = 750;
const TARGET_TIMEOUT_MS = 500;

const state = flow.get("robot") || {};
if (state.auto !== true) return null;

const vision = global.get("robot_vision");
const now = Date.now();
const streamFresh = vision && Number.isFinite(vision.recibido) && now - vision.recibido < STREAM_TIMEOUT_MS && vision.mensajes_recientes >= 3;
const targetFresh = vision && Number.isFinite(vision.ultimo_detectado) && now - vision.ultimo_detectado < TARGET_TIMEOUT_MS;
if (!streamFresh) {
    return { payload: { cmd: "stop", steer: 0, auto: false, origen: "vision" } };
}
if (!targetFresh || !Number.isFinite(vision.ultima_x)) {
    return { payload: { cmd: "stop", steer: 0, auto: true, origen: "vision" } };
}

const error = vision.ultima_x - 0.5;
let steer = 0;
if (Math.abs(error) > DEAD_BAND) {
    const proporcion = (Math.abs(error) - DEAD_BAND) / (0.5 - DEAD_BAND);
    steer = Math.round(Math.sign(error) * Math.min(1, proporcion) * AUTO_MAX_STEER);
}
return { payload: { cmd: "adelante", speed: AUTO_SPEED, steer, origen: "vision" } };
